import { useMemo } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { GitBranch, Network } from 'lucide-react';

/**
 * AICanvas — renders diagram nodes/edges generated by the backend
 * using React Flow (@xyflow/react).
 *
 * Props:
 *   flowData — { nodes: [...], edges: [...] } from the backend diagram_flow_parser,
 *              or null when no diagram is active.
 */
export default function AICanvas({ flowData }) {
  const initialNodes = useMemo(() => {
    if (!flowData?.nodes?.length) return [];
    return flowData.nodes.map((n) => ({
      id: n.id,
      type: n.type || 'default',
      position: n.position || { x: 0, y: 0 },
      data: { label: n.data?.label || n.id },
    }));
  }, [flowData]);

  const initialEdges = useMemo(() => {
    if (!flowData?.edges?.length) return [];
    return flowData.edges.map((e) => ({
      id: e.id,
      source: e.source,
      target: e.target,
      label: e.label || '',
      type: e.type || 'smoothstep',
      animated: e.animated || false,
    }));
  }, [flowData]);

  const [nodes, , onNodesChange] = useNodesState(initialNodes);
  const [edges, , onEdgesChange] = useEdgesState(initialEdges);

  // Reset when flowData changes — re-initialize from props
  const displayNodes = initialNodes.length ? initialNodes : nodes;
  const displayEdges = initialEdges.length ? initialEdges : edges;

  const isEmpty = !flowData?.nodes?.length;

  const defaultEdgeOptions = useMemo(
    () => ({
      style: { stroke: 'var(--dc-brand)', strokeWidth: 1.5 },
    }),
    []
  );

  return (
    <div
      className="h-full w-full relative"
      style={{
        background: 'var(--dc-surface-0)',
        border: '1px solid var(--dc-border)',
        borderRadius: 'var(--dc-radius-md)',
        overflow: 'hidden',
      }}
    >
      {isEmpty ? (
        <div
          className="h-full flex flex-col items-center justify-center gap-3"
          style={{ color: 'var(--dc-text-muted)' }}
        >
          <Network size={32} style={{ opacity: 0.4 }} />
          <p className="text-xs">No diagram loaded</p>
          <p className="text-[10px] flex items-center gap-1.5">
            <GitBranch size={11} />
            Use{' '}
            <code
              className="px-1.5 py-0.5 rounded"
              style={{
                background: 'var(--dc-brand-dim)',
                color: 'var(--dc-brand-glow)',
                fontSize: '10px',
              }}
            >
              /extract_diagram
            </code>
            in chat to generate a visual
          </p>
        </div>
      ) : (
        <ReactFlow
          nodes={displayNodes}
          edges={displayEdges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          defaultEdgeOptions={defaultEdgeOptions}
          fitView
          fitViewOptions={{ padding: 0.2 }}
          proOptions={{ hideAttribution: true }}
          colorMode="light"
        >
          <Background
            color="rgba(71, 85, 105, 0.12)"
            gap={20}
            size={1.5}
          />
          <Controls
            showInteractive={false}
            style={{
              backgroundColor: 'var(--dc-surface-2)',
              borderColor: 'var(--dc-border)',
            }}
          />
          <MiniMap
            nodeColor="var(--dc-brand)"
            maskColor="rgba(226,232,240,0.62)"
            style={{
              backgroundColor: 'var(--dc-surface-0)',
              border: '1px solid var(--dc-border)',
            }}
          />
        </ReactFlow>
      )}
    </div>
  );
}
